<script setup lang="ts">
definePageMeta({ middleware: "project-exists" });
const route = useRoute(); const router = useRouter(); const projectId = computed(() => String(route.params.projectId));
const analytics = useProjectAnalytics(projectId);
const project = shallowRef<TestProject | null>(null); const scenarios = useScenarios(projectId); const suitesSource = useTestSuites(projectId); const schedulesSource = useTestSchedules(projectId);
const periodPreset = ref("30d"); const startDate = ref(""); const endDate = ref(""); const timezone = ref(String(route.query.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || "Asia/Seoul"));
const trigger = ref(String(route.query.trigger || "all")); const scenarioId = ref(String(route.query.scenarioId || "")); const suiteId = ref(String(route.query.suiteId || "")); const scheduleId = ref(String(route.query.scheduleId || "")); const environmentName = ref(String(route.query.environmentName || ""));
const summary = computed(() => analytics.resources.summary.data.value); const timeseries = computed(() => analytics.resources.timeseries.data.value);
const loading = computed(() => analytics.resources.summary.pending.value); const partialErrors = computed(() => Object.entries(analytics.resources).filter(([, resource]) => resource.error.value).map(([key, resource]) => `${key}: ${resource.error.value}`));
onMounted(async () => { applyPreset(String(route.query.period || "30d"), false); if (typeof route.query.startDate === "string") startDate.value = route.query.startDate; if (typeof route.query.endDate === "string") endDate.value = route.query.endDate; const [projectValue] = await Promise.all([useProjects().get(projectId.value), scenarios.execute(), suitesSource.execute(), schedulesSource.execute()]); project.value = projectValue; await refresh(false); });
function localDate(date: Date): string { return new Intl.DateTimeFormat("en-CA", { timeZone: timezone.value, year: "numeric", month: "2-digit", day: "2-digit" }).format(date); }
function addDays(date: Date, amount: number): Date { const copy = new Date(date); copy.setUTCDate(copy.getUTCDate() + amount); return copy; }
function applyPreset(value: string, load = true): void { periodPreset.value = value; const now = new Date(); const today = localDate(now); if (value === "today") { startDate.value = today; endDate.value = today; } else if (["7d", "30d", "90d"].includes(value)) { const days = Number(value.slice(0, -1)); endDate.value = today; startDate.value = localDate(addDays(now, -(days - 1))); } else if (value === "thisMonth") { endDate.value = today; startDate.value = `${today.slice(0, 8)}01`; } else if (value === "lastMonth") { const first = new Date(`${today.slice(0, 8)}01T00:00:00Z`); const end = addDays(first, -1); endDate.value = localDate(end); startDate.value = `${endDate.value.slice(0, 8)}01`; } if (load) void refresh(); }
function query(): Record<string, string> { return Object.fromEntries(Object.entries({ startDate: startDate.value, endDate: endDate.value, timezone: timezone.value, trigger: trigger.value, scenarioId: scenarioId.value, suiteId: suiteId.value, scheduleId: scheduleId.value, environmentName: environmentName.value }).filter(([, value]) => value)); }
async function refresh(sync = true): Promise<void> { if (!startDate.value || !endDate.value) return; if (sync) await router.replace({ query: { ...query(), period: periodPreset.value } }); await analytics.load(query()); }
function reset(): void { trigger.value = "all"; scenarioId.value = ""; suiteId.value = ""; scheduleId.value = ""; environmentName.value = ""; timezone.value = Intl.DateTimeFormat().resolvedOptions().timeZone || "Asia/Seoul"; applyPreset("30d"); }
function rate(value: number | null | undefined): string { return value == null ? "—" : `${(value * 100).toFixed(1)}%`; }
function duration(value: number | null | undefined): string { return value == null ? "—" : `${Math.round(value).toLocaleString()}ms`; }
function selectBucket(point: AnalyticsTimeseriesPoint): void { periodPreset.value = "custom"; startDate.value = point.startDate.slice(0, 10); endDate.value = point.endDate.slice(0, 10); void refresh(); }
const runSeries = [{ key: "successCount" as const, label: "성공", color: "#16a34a" }, { key: "failedCount" as const, label: "실패", color: "#f97316" }, { key: "errorCount" as const, label: "오류", color: "#dc2626" }];
const regressionSeries = [{ key: "regressionCount" as const, label: "회귀", color: "#dc2626" }, { key: "resolvedCount" as const, label: "해결", color: "#16a34a" }, { key: "persistentFailureCount" as const, label: "지속 실패", color: "#7c3aed" }];
const durationSeries = [{ key: "averageDurationMs" as const, label: "평균", color: "#2563eb" }, { key: "medianDurationMs" as const, label: "중앙값", color: "#0891b2" }, { key: "p95DurationMs" as const, label: "P95", color: "#7c3aed" }, { key: "suiteAverageDurationMs" as const, label: "스위트 평균", color: "#f59e0b" }];
const errorSeries = [{ key: "consoleErrorCount" as const, label: "콘솔", color: "#7c3aed" }, { key: "networkErrorCount" as const, label: "네트워크", color: "#2563eb" }, { key: "http4xxCount" as const, label: "4xx", color: "#f59e0b" }, { key: "http5xxCount" as const, label: "5xx", color: "#dc2626" }, { key: "timeoutCount" as const, label: "타임아웃", color: "#475569" }];
</script>
<template>
  <div class="analytics-page">
    <AppPageHeader :title="`${project?.name || '프로젝트'} 품질 대시보드`" description="실행·회귀·스위트·예약 결과를 같은 기간 기준으로 분석합니다."><el-button @click="reset">초기화</el-button><el-button type="primary" :loading="loading" @click="refresh()">새로고침</el-button></AppPageHeader>
    <nav class="project-tabs" aria-label="프로젝트 메뉴"><NuxtLink :to="`/projects/${projectId}`">시나리오</NuxtLink><NuxtLink :to="`/projects/${projectId}/dashboard`">대시보드</NuxtLink><NuxtLink :to="`/projects/${projectId}/readiness`">실사용 준비도</NuxtLink><NuxtLink :to="`/projects/${projectId}/test-suites`">스위트</NuxtLink><NuxtLink :to="`/projects/${projectId}/schedules`">예약 실행</NuxtLink></nav>
    <section class="analytics-filter-panel" aria-label="대시보드 필터">
      <label>기간<select v-model="periodPreset" @change="applyPreset(periodPreset)"><option value="today">오늘</option><option value="7d">최근 7일</option><option value="30d">최근 30일</option><option value="90d">최근 90일</option><option value="thisMonth">이번 달</option><option value="lastMonth">지난 달</option><option value="custom">직접 설정</option></select></label>
      <label>시작일<input v-model="startDate" type="date" @change="periodPreset = 'custom'" /></label><label>종료일<input v-model="endDate" type="date" @change="periodPreset = 'custom'" /></label>
      <label>시간대<select v-model="timezone"><option>Asia/Seoul</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option></select></label><label>트리거<select v-model="trigger"><option value="all">전체</option><option value="manual">수동</option><option value="schedule">예약</option></select></label>
      <label>시나리오<select v-model="scenarioId"><option value="">전체</option><option v-for="item in scenarios.data.value" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>스위트<select v-model="suiteId"><option value="">전체</option><option v-for="item in suitesSource.data.value" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>예약<select v-model="scheduleId"><option value="">전체</option><option v-for="item in schedulesSource.data.value" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
      <label>환경<input v-model="environmentName" :placeholder="project?.environmentName || '전체'" /></label><el-button type="primary" @click="refresh()">적용</el-button>
    </section>
    <p v-if="summary" class="analytics-generated">조회 {{ summary.period.startDate.slice(0, 10) }} ~ {{ summary.period.endDate.slice(0, 10) }} · 직전 동일 기간 자동 비교 · 생성 {{ new Date(summary.generatedAt).toLocaleString() }}</p>
    <el-alert v-if="partialErrors.length" :title="`${partialErrors.length}개 영역을 불러오지 못했습니다. 정상 응답 영역은 계속 표시합니다.`" :description="partialErrors.join(' / ')" type="warning" show-icon :closable="false" />
    <div v-if="loading && !summary" class="form-panel"><el-skeleton :rows="10" animated /></div>
    <template v-else-if="summary">
      <section class="analytics-quality" :class="`analytics-quality--${summary.quality.state}`"><div><span>프로젝트 품질 상태</span><strong>{{ summary.quality.state }}</strong></div><p>{{ summary.quality.reasons.join(' ') }} (완료 실행 {{ summary.quality.sampleSize }}건)</p></section>
      <section class="analytics-metric-grid"><AnalyticsMetricCard label="완료 실행" :value="summary.metrics.completedRuns.toLocaleString()" :comparison="summary.comparisons.completedRuns" /><AnalyticsMetricCard :label="`성공 ${summary.metrics.successCount}건`" :value="rate(summary.metrics.successRate)" :comparison="summary.comparisons.successRate" tone="good" /><AnalyticsMetricCard :label="`실패·차단 ${summary.metrics.failedCount + summary.metrics.blockedCount}건`" :value="rate(summary.metrics.failureRate)" :comparison="summary.comparisons.failureRate" tone="bad" /><AnalyticsMetricCard :label="`오류 ${summary.metrics.errorCount}건`" :value="rate(summary.metrics.errorRate)" :comparison="summary.comparisons.errorRate" tone="bad" /><AnalyticsMetricCard :label="`회귀 ${summary.regression.regressionCount}건`" :value="rate(summary.regression.regressionRate)" :comparison="summary.comparisons.regressionRate" tone="bad" /><AnalyticsMetricCard label="평균 소요" :value="duration(summary.metrics.durations.averageMs)" :comparison="summary.comparisons.averageDurationMs" /><AnalyticsMetricCard label="스위트 성공률" :value="rate(summary.suites.successRate)" :comparison="summary.comparisons.suiteSuccessRate" /><AnalyticsMetricCard label="예약 완료율" :value="rate(summary.schedules.completionRate)" :comparison="summary.comparisons.scheduleCompletionRate" /></section>
      <section class="analytics-submetrics" aria-label="보조 품질 지표"><div><span>전체 단계 성공률</span><strong>{{ rate(summary.metrics.stepSuccessRate) }}</strong></div><div><span>실행 단계 성공률</span><strong>{{ rate(summary.metrics.executedStepSuccessRate) }}</strong></div><div><span>중앙값 / P95</span><strong>{{ duration(summary.metrics.durations.medianMs) }} / {{ duration(summary.metrics.durations.p95Ms) }}</strong></div><div><span>스위트 허용률</span><strong>{{ rate(summary.suites.acceptableRate) }}</strong></div><div><span>알림 발송 / 실패</span><strong>{{ summary.schedules.notificationSentCount }} / {{ summary.schedules.notificationFailedCount }}</strong></div></section>
      <section class="analytics-chart-grid" v-if="timeseries"><AnalyticsBarChart title="성공·실패·오류 추이" :points="timeseries.points" :series="runSeries" @select="selectBucket" /><AnalyticsBarChart title="회귀·해결·지속 실패" :points="timeseries.points" :series="regressionSeries" @select="selectBucket" /><AnalyticsBarChart title="실행 시간" :points="timeseries.points" :series="durationSeries" formatter="duration" @select="selectBucket" /><AnalyticsBarChart title="오류 발생" :points="timeseries.points" :series="errorSeries" @select="selectBucket" /></section>
      <section class="analytics-table-grid">
        <article class="analytics-table-panel"><h2>시나리오 품질</h2><div class="table-scroll"><table><thead><tr><th>시나리오</th><th>실행</th><th>성공률</th><th>회귀율</th><th>평균</th><th>최근</th></tr></thead><tbody><tr v-for="item in analytics.resources.scenarios.data.value?.items" :key="item.scenarioId"><td><NuxtLink :to="`/projects/${projectId}/scenarios/${item.scenarioId}`">{{ item.scenarioName }}</NuxtLink><small v-if="item.deleted"> 삭제됨</small></td><td>{{ item.runCount }}</td><td>{{ rate(item.successRate) }}</td><td>{{ rate(item.regressionRate) }}</td><td>{{ duration(item.averageDurationMs) }}</td><td>{{ item.lastRunStatus || '—' }}</td></tr><tr v-if="!analytics.resources.scenarios.data.value?.items.length"><td colspan="6">완료된 시나리오 실행이 없습니다.</td></tr></tbody></table></div></article>
        <article class="analytics-table-panel"><h2>자주 실패하는 단계</h2><div class="table-scroll"><table><thead><tr><th>단계</th><th>시나리오</th><th>실패</th><th>영향 실행</th><th>오류</th></tr></thead><tbody><tr v-for="item in analytics.resources['failing-steps'].data.value?.items" :key="`${item.scenarioId}-${item.stepId}`"><td>{{ item.stepName }} <small>{{ item.action }}</small></td><td>{{ item.scenarioName }}</td><td>{{ item.failureCount }}</td><td><NuxtLink :to="`/projects/${projectId}/scenarios/${item.scenarioId}/runs/${item.lastRunId}`">{{ item.affectedRunCount }}건</NuxtLink></td><td>{{ item.errorSample || '상태 실패' }}</td></tr><tr v-if="!analytics.resources['failing-steps'].data.value?.items.length"><td colspan="5">실패 단계가 없습니다.</td></tr></tbody></table></div></article>
        <article class="analytics-table-panel"><h2>스위트 안정성</h2><div class="table-scroll"><table><thead><tr><th>스위트</th><th>실행</th><th>성공률</th><th>허용률</th><th>평균</th></tr></thead><tbody><tr v-for="item in analytics.resources.suites.data.value?.items" :key="item.suiteId"><td><NuxtLink :to="`/projects/${projectId}/test-suites/${item.suiteId}`">{{ item.suiteName }}</NuxtLink><small v-if="item.deleted"> 삭제됨</small></td><td>{{ item.runCount }}</td><td>{{ rate(item.successRate) }}</td><td>{{ rate(item.acceptableRate) }}</td><td>{{ duration(item.averageDurationMs) }}</td></tr><tr v-if="!analytics.resources.suites.data.value?.items.length"><td colspan="5">완료된 스위트 실행이 없습니다.</td></tr></tbody></table></div></article>
        <article class="analytics-table-panel"><h2>예약 안정성</h2><div class="table-scroll"><table><thead><tr><th>예약</th><th>감지</th><th>완료율</th><th>건너뜀/실패</th><th>시작 지연</th><th>알림 실패</th></tr></thead><tbody><tr v-for="item in analytics.resources.schedules.data.value?.items" :key="item.scheduleId"><td><NuxtLink :to="`/projects/${projectId}/schedules/${item.scheduleId}`">{{ item.scheduleName }}</NuxtLink><small v-if="item.deleted"> 삭제됨</small></td><td>{{ item.executionCount }}</td><td>{{ rate(item.completionRate) }}</td><td>{{ item.skippedCount }}/{{ item.failedCount }}</td><td>{{ duration(item.averageStartDelayMs) }}</td><td>{{ item.notificationFailureCount }}</td></tr><tr v-if="!analytics.resources.schedules.data.value?.items.length"><td colspan="6">완료된 예약 실행이 없습니다.</td></tr></tbody></table></div></article>
        <article class="analytics-table-panel"><h2>오류 빈도</h2><div class="table-scroll"><table><thead><tr><th>종류</th><th>정규화된 오류</th><th>횟수</th><th>실행</th><th>상태</th></tr></thead><tbody><tr v-for="item in analytics.resources.errors.data.value?.items" :key="item.fingerprint"><td>{{ item.kind }}</td><td>{{ item.message }}</td><td>{{ item.count }}</td><td>{{ item.affectedRunCount }}</td><td>{{ item.statusCode ?? '—' }}</td></tr><tr v-if="!analytics.resources.errors.data.value?.items.length"><td colspan="5">수집된 오류가 없습니다.</td></tr></tbody></table></div></article>
        <article class="analytics-table-panel"><h2>최근 문제</h2><ul class="analytics-issues"><li v-for="item in analytics.resources['recent-issues'].data.value?.items" :key="`${item.type}-${item.id}`"><span :class="`issue-${item.severity}`">{{ item.type }}</span><div><NuxtLink :to="item.href">{{ item.title }}</NuxtLink><p>{{ item.detail }}</p></div><time>{{ new Date(item.occurredAt).toLocaleString() }}</time></li><li v-if="!analytics.resources['recent-issues'].data.value?.items.length">선택 기간에 발견된 문제가 없습니다.</li></ul></article>
      </section>
      <section class="analytics-note"><h2>AI 품질 요약</h2><p>숫자 지표와 품질 상태는 AI 없이 결정적으로 계산됩니다. 선택적 AI 서술 요약은 모델이 설정되지 않아 비활성화되어 있으며, 활성화하더라도 원본 수치나 상태 판정을 변경하지 않습니다.</p></section>
    </template>
    <AppEmptyState v-else title="분석 데이터를 불러오지 못했습니다" description="기간과 필터를 확인한 뒤 새로고침해 주세요." action-label="다시 시도" @action="refresh()" />
  </div>
</template>
